files.rules/ingest-integration-config-incomple:
# Log signature, latched · I-1.b (from E1 example 03). #1661 config_gap.py.
# Grouping on args[0] makes it untrusted (E2 decision 4): fine for lane 2.
apiVersion: medic.rules/v1
kind: Rule
id: ingest.integration-config-incomplete
title: SIEM integration is enabled but missing required settings
revision: 1
fault: {class: ingest, mode: I-1, causes: [I-1.b]}
lane: 2
signals:
  incomplete:
    log:
      signal: log_soc_daemon
      logger: {prefix: core.integrations.}
      level: [WARNING]
      template: {re2: '^%s configuration (still )?incomplete \(missing: %s\)'}
      keys: {integration: "args[0]"}
  complete:
    log:
      signal: log_soc_daemon
      logger: {prefix: core.integrations.}
      level: [INFO]
      template: {eq: '%s configuration complete; polling resumed after %d skipped polls'}
      keys: {integration: "args[0]"}
group_by: [integration]
when: {fn: latch, set: incomplete, clear: complete}
advice:
  summary: An integration is switched on but missing settings, so Vigil is skipping its polls.
  fix: >-
    Open Settings, Integrations and fill every required field for this
    integration (Elastic: Elasticsearch URL; OpenSearch: OpenSearch URL;
    Sentinel: client secret, subscription ID, resource group, workspace name;
    Defender: tenant and app credentials), or turn the integration off.

files.rules/pipeline-daemon-component-hung.yam:
# Multi-signal · P-3.a (from E1 example 04). Expected trust: trusted.
apiVersion: medic.rules/v1
kind: Rule
id: pipeline.daemon-component-hung
title: Daemon processor reports running but has done no work
revision: 1
fault: {class: pipeline, mode: P-3, causes: [P-3.a]}
lane: 3
detection: absence
shapes: [start_sh, helm]
signals:
  status:    {sample: {signal: daemon_health, key: components.processor}}
  processed: {sample: {signal: daemon_status.processor, key: processed}}
  uptime:    {sample: {signal: daemon_health, key: uptime_seconds}}
  arrivals:  {sample: {signal: daemon_status.poller, key: webhook_findings}}
when:
  all:
    - {fn: latest, signal: status, op: "==", value: running}
    - {fn: changes, signal: processed, window: 15m, op: "==", value: 0}
    - {fn: increase, signal: arrivals, window: 15m, op: ">", value: 0}
    - {fn: latest, signal: uptime, op: ">", value: 900}
for: 5m
keep_firing_for: 10m
advice:
  summary: Findings are arriving but the soc-daemon processor has processed none for 15 minutes while reporting running.
  fix: >-
    Send this incident to DeepTempo Support with the evidence report. Restarting
    soc-daemon usually restores the processor; record that you did so.

# Lane-1 variant of pipeline.daemon-component-hung for Compose (P-3.a lane 1: restart soc-daemon).
apiVersion: medic.rules/v1
kind: Rule
id: pipeline.daemon-processor-restart
title: Daemon processor hung on Compose (restart is a lane-1 fix)
revision: 1
fault: {class: pipeline, mode: P-3, causes: [P-3.a]}
lane: 1
detection: absence
shapes: [compose]
signals:
  status:    {sample: {signal: daemon_health, key: components.processor}}
  processed: {sample: {signal: daemon_status.processor, key: processed}}
  uptime:    {sample: {signal: daemon_health, key: uptime_seconds}}
  arrivals:  {sample: {signal: daemon_status.poller, key: webhook_findings}}
when:
  all:
    - {fn: latest, signal: status, op: "==", value: running}
    - {fn: changes, signal: processed, window: 15m, op: "==", value: 0}
    - {fn: increase, signal: arrivals, window: 15m, op: ">", value: 0}
    - {fn: latest, signal: uptime, op: ">", value: 900}
for: 5m
keep_firing_for: 10m
advice:
  summary: Findings are arriving but the soc-daemon processor has processed none for 15 minutes while reporting running.
  fix: >-
    Restart the soc-daemon container. In Phase 1 Medic can do this for you;
    in Phase 0 it only records that it would have.

files.suppression.yaml:
apiVersion: medic.suppression/v1
kind: Suppression
entries:
  - parent: {class: llm}
    children: {mode: P-4}
    why: Triage stalls whenever the LLM path is down (B5 P-4.a). Show the LLM fault, not the stall.
  - parent: {mode: L-5}
    children: {cause: P-2.e}
    why: A spent budget abandons runs (B5 P-2.e).
  - parent: {mode: L-3}
    children: {cause: P-2.e}
    why: LLM jobs with no consumer stall runs (B5 P-2.e).
  - parent: {cause: P-1.c}
    children: {cause: P-6.e}
    why: Memory distil depends on agent-serve being reachable (B5 P-6.e).
